mapper.select:
SELECT id, trip_no, vehicle_id, route_id, departure_time, booking_deadline, price, status, version, created_at, updated_at FROM transport_trip
status = #{status}
ORDER BY departure_time DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM transport_trip trip
INNER JOIN transport_route route
        ON route.id = trip.route_id
WHERE trip.vehicle_id = #{vehicleId}
  AND trip.status NOT IN ('COMPLETED', 'CANCELLED')
  AND trip.departure_time < #{arrivalTime}
  AND DATE_ADD(
        trip.departure_time,
        INTERVAL route.estimated_duration_minutes MINUTE
      ) > #{departureTime}

mapper.update:
UPDATE transport_trip
SET status = #{trip.status},
    version = #{trip.version},
    updated_at = #{trip.updatedAt}
WHERE id = #{trip.id}
  AND version = #{expectedVersion}
